using EventLensAI.Application.Features.Booth;using EventLensAI.Domain.Entities;using EventLensAI.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;
namespace EventLensAI.Infrastructure.Repositories;
internal sealed class ProfessionalCameraRepository(EventLensDbContext db):IProfessionalCameraRepository
{public Task<ProfessionalCamera?>GetAsync(Guid id,CancellationToken ct)=>db.ProfessionalCameras.FirstOrDefaultAsync(x=>x.Id==id,ct);public async Task<IReadOnlyList<ProfessionalCamera>>ListAsync(Guid org,CancellationToken ct)=>await db.ProfessionalCameras.AsNoTracking().Where(x=>x.OrganizationId==org).OrderBy(x=>x.Name).ToListAsync(ct);public Task AddAsync(ProfessionalCamera x,CancellationToken ct)=>db.ProfessionalCameras.AddAsync(x,ct).AsTask();public Task AddAdapterAsync(CameraAdapter x,CancellationToken ct)=>db.CameraAdapters.AddAsync(x,ct).AsTask();public Task AddLogAsync(CameraConnectionLog x,CancellationToken ct)=>db.CameraConnectionLogs.AddAsync(x,ct).AsTask();public Task<CameraCapabilityProfile?>GetCapabilitiesAsync(Guid id,CancellationToken ct)=>db.CameraCapabilityProfiles.AsNoTracking().FirstOrDefaultAsync(x=>x.ProfessionalCameraId==id,ct);public Task AddCapabilitiesAsync(CameraCapabilityProfile x,CancellationToken ct)=>db.CameraCapabilityProfiles.AddAsync(x,ct).AsTask();public Task AddEventAsync(ProfessionalCameraEvent x,CancellationToken ct)=>db.ProfessionalCameraEvents.AddAsync(x,ct).AsTask();}
